/**
 * Check if a given object implements the EtfResponseItemAccess interface.
 */
export function instanceOfEtfResponseItemAccess(value) {
    if (!("global" in value) || value["global"] === undefined)
        return false;
    if (!("plan" in value) || value["plan"] === undefined)
        return false;
    if (!("planBusiness" in value) || value["planBusiness"] === undefined)
        return false;
    return true;
}
export function EtfResponseItemAccessFromJSON(json) {
    return EtfResponseItemAccessFromJSONTyped(json, false);
}
export function EtfResponseItemAccessFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        global: json["global"],
        plan: json["plan"],
        planBusiness: json["plan_business"],
    };
}
export function EtfResponseItemAccessToJSON(json) {
    return EtfResponseItemAccessToJSONTyped(json, false);
}
export function EtfResponseItemAccessToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        global: value["global"],
        plan: value["plan"],
        plan_business: value["planBusiness"],
    };
}
